import unittest
import json
from datetime import date

class MockStorage:
    def __init__(self):
        self.data = {}
    def getItem(self, k):
        return self.data.get(k)
    def setItem(self, k, v):
        self.data[k] = v

class TestHealthTracker(unittest.TestCase):
    def setUp(self):
        self.storage = MockStorage()
        self.today = date.today().isoformat()

    def validate_input(self, steps, water):
        if not isinstance(steps, int) or steps < 0 or not isinstance(water, int) or water < 0:
            return False
        return True

    def test_save_valid_data(self):
        data = {'steps': 5000, 'waterIntakeMl': 2000}
        self.storage.setItem(self.today, json.dumps(data))
        stored = json.loads(self.storage.getItem(self.today))
        self.assertEqual(stored['steps'], 5000)
        self.assertEqual(stored['waterIntakeMl'], 2000)

    def test_input_validation_negative(self):
        self.assertFalse(self.validate_input(-1, 100))
        self.assertFalse(self.validate_input(100, -50))

    def test_dashboard_data_retrieval(self):
        self.storage.setItem(self.today, json.dumps({'steps': 1000, 'waterIntakeMl': 500}))
        raw_data = self.storage.getItem(self.today)
        data = json.loads(raw_data)
        self.assertEqual(data['steps'], 1000)
        self.assertEqual(data['waterIntakeMl'], 500)

    def test_dashboard_default_values(self):
        raw_data = self.storage.getItem('non-existent-date') or '{"steps": 0, "waterIntakeMl": 0}'
        data = json.loads(raw_data)
        self.assertEqual(data['steps'], 0)
        self.assertEqual(data['waterIntakeMl'], 0)

if __name__ == '__main__':
    unittest.main()
